(function () {
    var AviatorWinnerCommand;

    AviatorWinnerCommand = (function () {
        function AviatorWinnerCommand() {
        }

        AviatorWinnerCommand.prototype.execute = function (controller , topDate) {
            let url = 'api/Aviator/GetBigWinner?topDate=' + topDate;
			cc.PopupController.getInstance().showBusy();
            return cc.ServerConnector.getInstance().sendRequest(cc.SubdomainName.AVIATOR, url, function (response) {
                var obj = JSON.parse(response);
				cc.PopupController.getInstance().hideBusy();
                return controller.onGetBigWinnerResponse(obj);
            });
        };

        return AviatorWinnerCommand;

    })();

    cc.AviatorWinnerCommand = AviatorWinnerCommand;

}).call(this);